//! A simple, std-only hopscotch hash map (i32 -> i32), mirroring the
//! observable behavior of tsl::hopscotch_map for the ported test18 program.
//!
//! Layout: a flat `Vec` of bucket slots (power-of-two capacity, max load
//! factor 0.9) plus an overflow `Vec` used when a key's hop neighborhood is
//! full.

const NEIGHBORHOOD_SIZE: usize = 62;
const MAX_LOAD_FACTOR: f32 = 0.9;

#[derive(Clone, Copy)]
struct Slot {
    occupied: bool,
    key: i32,
    value: i32,
}

impl Slot {
    fn empty() -> Self {
        Slot {
            occupied: false,
            key: 0,
            value: 0,
        }
    }
}

pub struct HopscotchMap {
    buckets: Vec<Slot>,
    mask: usize,
    overflow: Vec<(i32, i32)>,
    size: usize,
}

impl HopscotchMap {
    pub fn new() -> Self {
        HopscotchMap {
            buckets: Vec::new(),
            mask: 0,
            overflow: Vec::new(),
            size: 0,
        }
    }

    /// Mirror tsl::hopscotch_map::reserve: bucket_count becomes
    /// next_power_of_two(ceil(count as f32 / 0.9)), with 0 staying 0.
    pub fn reserve(&mut self, count: usize) {
        let needed = Self::min_buckets_for(count);
        if needed > self.buckets.len() {
            self.rehash(needed);
        }
    }

    /// Smallest power-of-two bucket count able to hold `count` entries at a
    /// 0.9 max load factor. The division is performed in f32, mirroring the
    /// C++ `float(count) / 0.9f`.
    fn min_buckets_for(count: usize) -> usize {
        if count == 0 {
            return 0;
        }
        let needed = (count as f32 / MAX_LOAD_FACTOR).ceil() as usize;
        needed.next_power_of_two()
    }

    /// Home bucket index for a key (identity hash, masked).
    fn home(&self, key: i32) -> usize {
        (key as u32 as usize) & self.mask
    }

    /// Grow (double + rehash) when inserting one more element would exceed
    /// 0.9 * bucket_count.
    fn maybe_grow(&mut self) {
        let capacity = self.buckets.len();
        let allowed = (capacity as f32 * MAX_LOAD_FACTOR) as usize;
        if self.size + 1 > allowed {
            let new_capacity = if capacity == 0 { 2 } else { capacity * 2 };
            self.rehash(new_capacity);
        }
    }

    fn rehash(&mut self, new_capacity: usize) {
        debug_assert!(new_capacity == 0 || new_capacity.is_power_of_two());
        let old_buckets = std::mem::replace(
            &mut self.buckets,
            vec![Slot::empty(); new_capacity],
        );
        self.mask = new_capacity.wrapping_sub(1);

        let old_overflow = std::mem::take(&mut self.overflow);
        let old_size = self.size;
        self.size = 0;

        for slot in old_buckets.iter() {
            if slot.occupied {
                self.insert_unchecked(slot.key, slot.value);
            }
        }
        for (key, value) in old_overflow {
            self.insert_unchecked(key, value);
        }
        debug_assert_eq!(self.size, old_size);
    }

    /// Insert without any growth checks (used during rehash).
    fn insert_unchecked(&mut self, key: i32, value: i32) {
        let home = self.home(key);
        // Probe the neighborhood starting at the home bucket; wrap around.
        for offset in 0..NEIGHBORHOOD_SIZE.min(self.buckets.len()) {
            let idx = (home + offset) & self.mask;
            if !self.buckets[idx].occupied {
                self.buckets[idx] = Slot {
                    occupied: true,
                    key,
                    value,
                };
                self.size += 1;
                return;
            }
        }
        // Neighborhood full: fall back to the overflow list.
        self.overflow.push((key, value));
        self.size += 1;
    }

    /// Insert or overwrite the value for `key`.
    pub fn insert(&mut self, key: i32, value: i32) {
        self.maybe_grow();
        let home = self.home(key);
        for offset in 0..NEIGHBORHOOD_SIZE.min(self.buckets.len()) {
            let idx = (home + offset) & self.mask;
            if self.buckets[idx].occupied && self.buckets[idx].key == key {
                self.buckets[idx].value = value;
                return;
            }
        }
        for entry in self.overflow.iter_mut() {
            if entry.0 == key {
                entry.1 = value;
                return;
            }
        }
        self.insert_unchecked(key, value);
    }

    pub fn size(&self) -> usize {
        self.size
    }

    pub fn bucket_count(&self) -> usize {
        self.buckets.len()
    }

    pub fn overflow_size(&self) -> usize {
        self.overflow.len()
    }
}

