cat > /tmp/check18.c <<'EOF'
#include <stdio.h>
#include <math.h>

static unsigned long next_pow2(unsigned long n){
    unsigned long p = 1;
    while (p < n) p <<= 1;
    return p;
}

int main(void){
    FILE *f = fopen("/tmp/test18_reference.tsv", "r");
    if (!f) { perror("open"); return 1; }
    char key[64];
    unsigned long size, bucket, overflow;
    int total = 0, mismatches = 0, checked = 0;
    char noargs_line[128] = "", count18_line[128] = "";
    char line[256];
    while (fgets(line, sizeof line, f)) {
        total++;
        if (sscanf(line, "%63s", key) != 1) continue;
        /* key is up to first tab */
        char *tab = line;
        while (*tab && *tab != '\t') tab++;
        if (!*tab) continue;
        char kbuf[64];
        int klen = (int)(tab - line);
        if (klen >= 64) klen = 63;
        for (int i = 0; i < klen; i++) kbuf[i] = line[i];
        kbuf[klen] = 0;
        unsigned long s, b, o;
        if (sscanf(tab + 1, "%lu %lu %lu", &s, &b, &o) != 3) continue;
        if (kbuf[0]=='n') { /* noargs */
            snprintf(noargs_line, sizeof noargs_line, "%lu %lu %lu", s, b, o);
            continue;
        }
        unsigned long count = strtoul(kbuf, NULL, 10);
        if (count == 18)
            snprintf(count18_line, sizeof count18_line, "%lu %lu %lu", s, b, o);
        checked++;
        unsigned long pb;
        if (count == 0) pb = 0;
        else {
            float q = (float)count / 0.9f;
            pb = next_pow2((unsigned long)ceilf(q));
        }
        if (s != count || b != pb || o != 0) {
            mismatches++;
            printf("MISMATCH: %s\t%lu %lu %lu  predicted: %lu %lu 0\n",
                   kbuf, s, b, o, count, pb);
        }
    }
    fclose(f);
    printf("total rows (incl noargs): %d\n", total);
    printf("checked count rows: %d\n", checked);
    printf("mismatches: %d\n", mismatches);
    printf("noargs:    %s\n", noargs_line);
    printf("count=18:  %s\n", count18_line);
    printf("noargs == count=18: %s\n",
           (noargs_line[0] && !strcmp_(noargs_line, count18_line)) ? "yes" : "no");
    return 0;
}
EOF
sed -i 's/strcmp_/strcmp/' /tmp/check18.c
sed -i '3a #include <string.h>\n#include <stdlib.h>' /tmp/check18.c
gcc -O2 -o /tmp/check18 /tmp/check18.c -lm && /tmp/check18

